using System;using UnityEngine;
namespace GreyHarbor {public sealed partial class RaidVerification {
 void EdgeRules310(){
  foreach(var size in new[]{new Vector2Int(1600,900),new Vector2Int(2560,1440),new Vector2Int(1280,1024),new Vector2Int(2560,1080)}){
   bool quiet=true;foreach(var uv in new[]{new Vector2(.5f,.5f),new Vector2(.2f,.8f),new Vector2(.8f,.2f)})quiet&=EdgePan309.Desired(new Vector2(uv.x*size.x,uv.y*size.y),size.x,size.y).sqrMagnitude<.000001f;
   Check(quiet,"middle60-percent remains stable "+size);
   bool continuous=true;for(int deg=0;deg<360;deg+=5){var d=new Vector2(Mathf.Cos(deg*Mathf.Deg2Rad),Mathf.Sin(deg*Mathf.Deg2Rad));float reach=Mathf.Min(Mathf.Abs(d.x)<.00001f?float.PositiveInfinity:size.x*.5f/Mathf.Abs(d.x),Mathf.Abs(d.y)<.00001f?float.PositiveInfinity:size.y*.5f/Mathf.Abs(d.y));var point=new Vector2(size.x*.5f,size.y*.5f)+d*reach*.9999f;var pan=EdgePan309.Desired(point,size.x,size.y);var projected=new Vector2(pan.x,pan.y*Mathf.Sin(RaidCamera.ViewTilt310*Mathf.Deg2Rad));continuous&=Vector2.Dot(projected.normalized,d)>.99999f&&pan.magnitude>3.99f&&pan.magnitude<=4.00001f;}
   Check(continuous,"all72 screen angles stay continuous with4m total cap "+size);
   var slant=EdgePan309.Desired(new Vector2(size.x,size.y*.65f),size.x,size.y);Check(slant.x>0&&slant.y>0,"single right edge permits diagonal movement "+size);
   Check(EdgePan309.Desired(new Vector2(size.x*.8f+1,size.y*.5f),size.x,size.y).x>0&&EdgePan309.Desired(new Vector2(size.x*.8f-1,size.y*.5f),size.x,size.y)==Vector2.zero,"outer20-percent trigger boundary is gradual "+size);
  }
  Check(EdgePan309.Desired(new Vector2(-1,100),1600,900)==Vector2.zero&&EdgePan309.Desired(new Vector2(1601,100),1600,900)==Vector2.zero&&EdgePan309.Desired(Vector2.one,0,0)==Vector2.zero,"outside and invalid viewport do not create pan targets");
  var right=new Vector2(1600,450);var center=new Vector2(800,450);float reference=0;
  foreach(int fps in new[]{30,60,120}){var state=new EdgePan309.State();for(int i=0;i<Mathf.RoundToInt(fps*EdgePan309.SettleSeconds);i++)EdgePan309.Step(state,right,1600,900,true,1f/fps);Check(state.Offset.x>3.78f&&state.Offset.x<3.82f,"spring reaches about95-percent after1.2seconds FPS="+fps);if(fps==30)reference=state.Offset.x;else Check(Mathf.Abs(state.Offset.x-reference)<.00001f,"spring response independent of frame rate "+fps);
   for(int i=0;i<Mathf.CeilToInt(fps*(EdgePan309.SettleSeconds*4+EdgePan309.ReturnDelay));i++)EdgePan309.Step(state,center,1600,900,true,1f/fps);Check(state.Offset==Vector2.zero&&state.Velocity==Vector2.zero,"long central dwell completes smooth return "+fps);}
  var first=new EdgePan309.State();EdgePan309.Step(first,right,1600,900,true,1f/60);Check(first.Offset.x>0&&first.Offset.x<.04f,"first frame eases into motion with no jump");
  var hold=new EdgePan309.State();EdgePan309.Step(hold,right,1600,900,true,EdgePan309.SettleSeconds*3);var before=hold.Offset;EdgePan309.Step(hold,center,1600,900,true,.1f);Check(hold.Target==Vector2.right*4&&hold.CenterTime>.099f&&hold.Offset.x>=before.x,"brief central pass preserves prior edge target");EdgePan309.Step(hold,right,1600,900,true,.01f);Check(hold.CenterTime==0&&hold.Target==Vector2.right*4,"return to edge cancels pending recenter");
  EdgePan309.Step(hold,center,1600,900,true,EdgePan309.ReturnDelay-.01f);Check(hold.Target.x==4,"no return before.65-second central dwell");EdgePan309.Step(hold,center,1600,900,true,.011f);Check(hold.Target==Vector2.zero&&Mathf.Abs(hold.CenterTime-EdgePan309.ReturnDelay)<.00001f&&Vector2.Distance(hold.Offset,before)<.01f,"delay crossing starts recenter without position jump");EdgePan309.Step(hold,center,1600,900,true,EdgePan309.SettleSeconds);Check(hold.Offset.x>0&&hold.Offset.x<.23f,"return glides toward center over next1.2seconds");
  var a=new EdgePan309.State();var b=new EdgePan309.State();EdgePan309.Step(a,right,1600,900,true,1);EdgePan309.Step(b,right,1600,900,true,1);EdgePan309.Step(a,center,1600,900,true,EdgePan309.ReturnDelay+.15f);for(int i=0;i<Mathf.RoundToInt((EdgePan309.ReturnDelay+.15f)*100);i++)EdgePan309.Step(b,center,1600,900,true,.01f);Check(Vector2.Distance(a.Offset,b.Offset)<.00001f&&Vector2.Distance(a.Velocity,b.Velocity)<.0001f,"frame straddling return delay agrees with small time steps");
  var reverse=new EdgePan309.State();EdgePan309.Step(reverse,right,1600,900,true,EdgePan309.SettleSeconds*3);EdgePan309.Step(reverse,new Vector2(0,450),1600,900,true,1f/60);Check(reverse.Offset.x>3.9f&&reverse.Velocity.x<0,"opposite edge reverses smoothly instead of snapping");EdgePan309.Step(reverse,new Vector2(0,450),1600,900,true,EdgePan309.SettleSeconds);Check(reverse.Offset.x< -3.55f&&reverse.Offset.magnitude<=4,"opposite target reached smoothly within4m");
  var freeze=new EdgePan309.State();EdgePan309.Step(freeze,right,1600,900,true,.3f);EdgePan309.Step(freeze,center,1600,900,true,.1f);var x=freeze.Offset;var v=freeze.Velocity;float wait=freeze.CenterTime;EdgePan309.Step(freeze,center,1600,900,false,3);EdgePan309.Step(freeze,center,1600,900,true,0);Check(freeze.Offset==x&&freeze.Velocity==v&&freeze.CenterTime==wait,"menu/paused/zero-time tick freezes position velocity and dwell");
  bool bounded=true;for(int i=0;i<1000;i++){float angle=i*.29f;var p=new Vector2(800+800*Mathf.Cos(angle),450+450*Mathf.Sin(angle));EdgePan309.Step(freeze,p,1600,900,true,1f/60);bounded&=freeze.Offset.magnitude<=4.00001f&& !float.IsNaN(freeze.Offset.x);}Check(bounded,"rapid360-degree pointer changes never exceed4m or become unstable");freeze.Reset();Check(freeze.Offset==Vector2.zero&&freeze.Velocity==Vector2.zero&&freeze.CenterTime==0&&freeze.Target==Vector2.zero,"view reset clears velocity and pending return too");
 }
}}
